-- =============================================================================
-- 191_seed_icd10_catalog.sql
-- Nap DANH MUC ICD-10 TIENG VIET (15554 ma) thay cho 41 dong seed demo.
--
-- Nguon: cong tra cuu ICD-10 chinh thuc cua Cuc Quan ly Kham chua benh - Bo Y te
-- (https://icd.kcb.vn), ban ICD-10 tieng Viet theo QD 4469/QD-BYT.
--
-- Vi sao can: bang IcdCodes truoc do chi co 41 ma demo -> bac si go chan doan nao
-- cung gan nhu khong ra. Ma ICD la BAT BUOC de day XML 4210 thanh toan BHYT, nen
-- thieu danh muc la chan ca luong bao hiem chu khong chi bat tien.
--
-- Idempotent: chi INSERT ma chua ton tai; chay lai khong nhan doi. KHONG dung toi
-- 41 dong seed cu (co the da duoc tham chieu trong benh an da tao).
-- =============================================================================

SET QUOTED_IDENTIFIER ON;
SET NOCOUNT ON;

IF OBJECT_ID('tempdb..#IcdSeed') IS NOT NULL DROP TABLE #IcdSeed;
-- COLLATE DATABASE_DEFAULT: tempdb mang collation server (SQL_Latin1) con DB HIS la
-- Vietnamese_CI_AS -> khong ep thi phep so sanh Code o buoc INSERT bao collation conflict.
CREATE TABLE #IcdSeed (
    Code        nvarchar(20)  COLLATE DATABASE_DEFAULT NOT NULL PRIMARY KEY,
    Name        nvarchar(500) COLLATE DATABASE_DEFAULT NULL,
    ChapterCode nvarchar(20)  COLLATE DATABASE_DEFAULT NULL,
    GroupCode   nvarchar(20)  COLLATE DATABASE_DEFAULT NULL
);



















                      IsNotifiable, IsActive, CreatedAt, CreatedBy, IsDeleted)
SELECT NEWID(), s.Code, s.Name, s.ChapterCode, s.GroupCode, 1,
       0, 1, SYSUTCDATETIME(), NULL, 0
FROM #IcdSeed s
WHERE NOT EXISTS (SELECT 1 FROM IcdCodes c WHERE c.Code = s.Code);

PRINT CONCAT('191: da nap ', @@ROWCOUNT, ' ma ICD-10 moi.');
DROP TABLE #IcdSeed;
GO
